def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    needy_pressure = 0.0
    rich_pressure = 0.0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            opp_hp = opp.get('hp', 10)
            opp_no_water = opp.get('no_water_days', 0)
            opp_budget = opp.get('budget', 0)
            if opp_hp <= 3 or opp_no_water >= 1:
                needy_pressure = max(needy_pressure, min(float(opp_budget), DAILY_SALARY * 1.2))
            if opp_budget >= DAILY_SALARY * 3:
                rich_pressure = max(rich_pressure, DAILY_SALARY * 0.95)

    if not alive:
        return max(0.0, min(float(budget), DAILY_SALARY * 0.35))

    slots = max(1, int(supply // WATER_REQ))
    competitors = len(alive) + 1
    scarcity = competitors - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    pressure = max(highest_prev, needy_pressure, rich_pressure)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1

    if budget <= 0:
        return 0.0

    if slots >= competitors:
        if urgency >= 3:
            bid = DAILY_SALARY * 0.28
        else:
            bid = DAILY_SALARY * 0.12
        return max(0.0, min(float(budget), bid))

    if urgency >= 5:
        bid = max(DAILY_SALARY * 0.95, pressure + 2.0)
    elif urgency >= 3:
        if pressure >= DAILY_SALARY * 1.3:
            bid = DAILY_SALARY * 0.72
        else:
            bid = max(DAILY_SALARY * 0.62, min(pressure + 1.5, DAILY_SALARY * 1.02))
    else:
        if pressure >= DAILY_SALARY * 1.15:
            bid = DAILY_SALARY * 0.22
        elif pressure >= DAILY_SALARY * 0.8:
            bid = DAILY_SALARY * 0.38
        else:
            bid = max(DAILY_SALARY * 0.34, avg_prev + 1.0)

    if scarcity >= 3:
        bid += DAILY_SALARY * 0.12
    elif scarcity >= 2:
        bid += DAILY_SALARY * 0.07
    elif scarcity <= 0:
        bid -= DAILY_SALARY * 0.08

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.92)
    elif budget < DAILY_SALARY * 2 and urgency < 3:
        bid = min(bid, DAILY_SALARY * 0.58)

    if hp >= 8 and no_water == 0 and pressure >= DAILY_SALARY * 1.2 and slots == 1:
        bid = min(bid, DAILY_SALARY * 0.2)

    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents alive, bid as needed but stay budget-safe.
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Estimate a competitive target: slightly above the upper-middle yesterday bid.
    # This aims to outbid Cindy when she pressures, but avoid matching her highest bids.
    if yesterday_bids:
        yesterday_bids_sorted = sorted(yesterday_bids)
        # Choose 70th percentile-ish index without float indexing.
        k = int(0.7 * (len(yesterday_bids_sorted) - 1)) if len(yesterday_bids_sorted) > 1 else 0
        target = float(yesterday_bids_sorted[k])
        # If Cindy-like pressure existed (very high bid), don't fully mirror; add a small premium.
        highest = float(max(yesterday_bids_sorted))
        if highest >= DAILY_SALARY * 1.4:
            desired = min(highest * 0.78, target + 6.0)
        else:
            desired = target + 3.0
    else:
        desired = DAILY_SALARY * 0.55

    # Risk control based on my HP and consecutive no-water days.
    # If I'm low HP or already accumulating no-water days, increase bid.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        desired *= 1.35
    elif my_hp <= 4.0:
        desired *= 1.15

    # Supply-aware adjustment: higher supply reduces need to overbid.
    # supply is in [15,25]; map to a factor.
    if supply >= 22.0:
        desired *= 0.92
    elif supply <= 17.0:
        desired *= 1.08

    # Budget cap and non-negative.
    bid = max(0.0, min(my_budget, desired))

    # Ensure we don't bid trivially low when we still need water.
    # If my budget allows, keep a minimum bid threshold.
    min_reasonable = DAILY_SALARY * 0.35
    if my_budget >= min_reasonable:
        bid = max(bid, min_reasonable)

    return float(bid)
